// Pure: guesses the repo's deterministic checks from which files exist, and returns the factory/checks.sh to write.
// factory/bin/gate runs this script in a job's worktree; exit 0 means the gate passes.
const HEADER = `#!/bin/sh
# The repo's deterministic checks. factory/bin/gate runs the main checkout's copy of
# this file inside a job's worktree; exit 0 means the gate passes.
# Generated by the Eminzo installer from the files found in the repo: review it.
set -e
`;

const NO_TEST_PLACEHOLDER = /no test specified/i;
const has = (files, name) => files.includes(name);

function nodeCommand(files) {
  if (has(files, 'pnpm-lock.yaml')) return 'pnpm test';
  if (has(files, 'yarn.lock')) return 'yarn test';
  return 'npm test';
}

function pythonHasTests(files, read) {
  if (['pytest.ini', 'tox.ini', 'conftest.py'].some((f) => has(files, f))) return true;
  return ['pyproject.toml', 'setup.cfg', 'requirements.txt', 'requirements-dev.txt'].some((f) => has(files, f) && /pytest/i.test(read(f) ?? ''));
}

function withBody(body) {
  return `${HEADER}\n${body}\n`;
}

/**
 * @param {{ files: string[], packageJson: object | null, read: (file: string) => string }} input `files` are the repo root entries.
 * @returns {{ stack: 'node' | 'go' | 'rust' | 'python' | 'maven' | 'gradle' | 'none', script: string }}
 */
export function detectChecks({ files, packageJson, read }) {
  const test = packageJson?.scripts?.test;
  if (has(files, 'package.json') && typeof test === 'string' && test.trim() && !NO_TEST_PLACEHOLDER.test(test)) {
    return { stack: 'node', script: withBody(nodeCommand(files)) };
  }
  if (has(files, 'go.mod')) return { stack: 'go', script: withBody('go test ./...') };
  if (has(files, 'Cargo.toml')) return { stack: 'rust', script: withBody('cargo test') };
  if (pythonHasTests(files, read)) return { stack: 'python', script: withBody('python -m pytest') };
  if (has(files, 'pom.xml')) return { stack: 'maven', script: withBody('mvn -B -q test') };
  if (has(files, 'gradlew')) return { stack: 'gradle', script: withBody('./gradlew test') };
  return {
    stack: 'none',
    script: withBody(`# No test command was detected in this repo, so this gate checks nothing yet.
# Replace the next lines with your test, lint and typecheck commands, for example: npm test
echo "factory/checks.sh: TODO add this repo's test command" >&2
exit 0`),
  };
}
